def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    rows is an iterable of mappings; columns is an ordered iterable of unique
    string column names. Returns a str with a CSV header followed by one
    record per row. Fields use comma delimiters, CRLF record endings, and
    RFC 4180 minimal quoting with quote doubling. Missing fields and None
    become empty strings; other values become str(value). Unselected fields
    are ignored. Inputs are not mutated.

    Raises ValueError for duplicate or non-string column names.
    """
    cols = list(columns)
    seen = set()
    for col in cols:
        if not isinstance(col, str):
            raise ValueError("column names must be strings")
        if col in seen:
            raise ValueError("duplicate column name: %r" % (col,))
        seen.add(col)

    def quote_field(value):
        if value is None:
            return ""
        text = str(value)
        if any(ch in text for ch in ('"', ",", "\r", "\n")):
            return '"' + text.replace('"', '""') + '"'
        return text

    lines = [",".join(cols)]
    for row in rows:
        lines.append(",".join(quote_field(row.get(col)) for col in cols))
    return "".join(line + "\r\n" for line in lines)

